            click.echo(f"• Analysis saved to: {state['field_dependency_filepath']}")

    if state["metadata"].get("mock_server_generated", False):
        click.echo(f"• Mock server generated successfully")
        if "mock_server_dir" in state:
            click.echo(f"• Mock server directory: {state['mock_server_dir']}")
        if "mock_server_process" in state and state["mock_server_process"]:
            click.echo(f"• Mock server running (PID: {state['mock_server_process'].pid})")

    click.echo(f"• Results saved to: {state['output_dir']}")


    # Display any errors
    if state["errors"]:
        click.echo(f"\nErrors ({len(state['errors'])}):")
        for error in state["errors"]:
            click.echo(f"   {error}")

    # Add performance metrics if available
    if "duration" in metadata:
        click.echo(f"\nProcessing time: {metadata['duration']:.2f} seconds")

    if "estimated_tokens" in metadata:
        tokens = metadata["estimated_tokens"]
        click.echo(f"Token usage: ~{tokens.get('estimated_input_tokens', 0)} input + {tokens.get('max_output_tokens', 0)} output")

    return state

# SetupMandate Flow Pattern for Connector Implementation

**🎯 GENERIC PATTERN FILE FOR ANY NEW CONNECTOR**

This document provides comprehensive, reusable patterns for implementing the SetupMandate flow in **ANY** payment connector within the UCS (Universal Connector Service) system. These patterns are extracted from successful connector implementations across 8 connectors (Adyen, Stripe, Cybersource, ACI, Authorizedotnet, Noon, Novalnet, Payload) and can be consumed by AI to generate consistent, production-ready SetupMandate flow code for any payment gateway.

> **🏗️ UCS-Specific:** This pattern is tailored for UCS architecture using RouterDataV2, ConnectorIntegrationV2, and domain_types. This pattern focuses on recurring payment setup and mandate creation.

