        fn get_request_body(
            &self,
            req: &RouterDataV2<...>,
        ) -> CustomResult<RequestContent, ConnectorError> {
            let request = IncrementalAuthRequest::try_from(&req.request)?;
            Ok(RequestContent::FormUrlEncoded(request))
        }
    }
);
```

